//C - Evacuation:
//Assunto: Flow;
#include<bits/stdc++.h>
#define fi first
#define se second
#define pb push_back
#define all(x) x.begin(), x.end()
#define rall(x) x.rbegin(), x.rend()
#define loop(i, a, b) for(int i = a; i < b; i++)
#define loopBack(i, a, b) for(int i = a; i >= b; i--)
#define INF INT_MAX
#define LINF LLONG_MAX
#define DINF DBL_MAX
#define MAX 150
#define MOD 1000
using namespace std;
typedef long long int ll;
typedef pair<int, int> ii;

struct FlowEdge {
    int v, u;
    ll cap, flow = 0;
    FlowEdge(int v, int u, ll cap) : v(v), u(u), cap(cap) {}
};

struct Dinic {
    const ll flow_inf = 1e18;
    vector<FlowEdge> edges;
    vector<vector<int>> adj;
    int n, m = 0;
    int s, t;
    vector<int> level, ptr; 
    queue<int> q;

    Dinic(int n, int s, int t) : n(n), s(s), t(t) {
        adj.resize(n);
        level.resize(n);
        ptr.resize(n);
    }

    void add(int v, int u, ll cap) {
        edges.emplace_back(v, u, cap);
        edges.emplace_back(u, v, 0);
        adj[v].push_back(m); 
        adj[u].push_back(m+1);
        m += 2;
    }

    bool bfs() {
        while(!q.empty()) {
            int v = q.front();
            q.pop();
            for(int viz : adj[v]) {
                if(edges[viz].cap - edges[viz].flow < 1) continue;
                if(level[edges[viz].u] != -1) continue; 
                level[edges[viz].u] = level[v] + 1;
                q.push(edges[viz].u);
            }
        }
        return level[t] != -1;
    }

    ll dfs(int v, ll pushed) {
        if(pushed == 0) return 0;
        if(v == t) return pushed;
        for(int &i = ptr[v]; i < (int)adj[v].size(); i++) { 
            int viz = adj[v][i];
            int u = edges[viz].u;
            if(level[v] + 1 != level[u] || edges[viz].cap - edges[viz].flow < 1) continue;
            ll tr = dfs(u, min(pushed, edges[viz].cap - edges[viz].flow));
            if(tr == 0) continue; 

            edges[viz].flow += tr;
            edges[viz ^ 1].flow -= tr; 
            return tr;
        }
        return 0;
    }

    ll flow() {
        ll f = 0;
        while(true) {
            fill(all(level), -1);
            level[s] = 0;
            q.push(s);
            if(!bfs()) break; 
            fill(all(ptr), 0);
            while(ll pushed = dfs(s, flow_inf))
                f += pushed;
        }
        return f;
    }
};

int pos[MAX][MAX], matTempo[MAX][MAX], matAlc[MAX][MAX];

vector<ii> pegaVizinhos(int i, int j, vector<string> mat, int n) {
    vector<ii> viz;
    if(i + 1 < n) viz.pb({i+1, j});
    if(i - 1 >= 0) viz.pb({i-1, j});
    if(j + 1 < n) viz.pb({i, j+1});
    if(j - 1 >= 0) viz.pb({i, j-1});
    return viz;
}

void criaMatTempo(int i, int j, vector<string> sc, int n, int currT) {
    if(i >= n || i < 0 || j >= n || j < 0 || (!isdigit(sc[i][j]) && sc[i][j] != 'Z') || (matTempo[i][j] != -1 and matTempo[i][j] <= currT)) return;
    if(matTempo[i][j] == -1)
        matTempo[i][j] = currT;
    else 
        matTempo[i][j] = min(currT, matTempo[i][j]);
    criaMatTempo(i+1, j, sc, n, currT+1);
    criaMatTempo(i-1, j, sc, n, currT+1);
    criaMatTempo(i, j+1, sc, n, currT+1);
    criaMatTempo(i, j-1, sc, n, currT+1);
}

void criaMatAlc(int i, int j, vector<string> sc, int n, int currT) {
    if(i >= n || i < 0 || j >= n || j < 0 || (matAlc[i][j] != -1 and matAlc[i][j] <= currT) || !isdigit(sc[i][j])) return;
    if(matAlc[i][j] == -1)
        matAlc[i][j] = currT;
    else 
        matAlc[i][j] = min(currT, matAlc[i][j]);
    criaMatAlc(i+1, j, sc, n, currT+1);
    criaMatAlc(i-1, j, sc, n, currT+1);
    criaMatAlc(i, j+1, sc, n, currT+1);
    criaMatAlc(i, j-1, sc, n, currT+1);
}

int main() {
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    // freopen("in.txt", "r", stdin);
    int n, t, n2, nMax, iZ, jZ;
    string aux;

    cin >> n >> t;
    n2 = n * n;
    nMax = n2 * 2;
    Dinic grafo = Dinic(nMax + 2, 0, nMax + 1);
    vector<string> sc(n), caps(n);

    //Calcular Posicao
    int cnt = 1;
    loop(i, 0, n) {
        loop(j, 0, n) {
            pos[i][j] = cnt;
            cnt++;
        } 
    }

    loop(i, 0, n) {
        cin >> sc[i];
        loop(j, 0, n) {
            if(sc[i][j] == 'Z') {
                iZ = i;
                jZ = j;
            }
        }
    }
    loop(i, 0, n) cin >> caps[i];

    memset(matTempo, -1, sizeof(matTempo));
    criaMatTempo(iZ, jZ, sc, n, 0);
    loop(i, 0, n) {
        loop(j, 0, n) {
            if(matTempo[i][j] == -1 and isdigit(sc[i][j])) matTempo[i][j] = t;
        }
    }

    loop(i, 0, n) {
        loop(j, 0, n) {
            memset(matAlc, -1, sizeof(matAlc));
            if(isdigit(sc[i][j])) {
                int lmt = sc[i][j] - '0';
                grafo.add(0, pos[i][j], lmt);
                criaMatAlc(i, j, sc, n, 0);
                loop(k, 0, n) {
                    loop(l, 0, n) {
                        if(matAlc[k][l] != -1 and matTempo[k][l] != -1 and matAlc[k][l] <= matTempo[k][l] and matAlc[k][l] <= t) {
                            bool crt = true;
                            if(matAlc[k][l] == matTempo[k][l]) {
                                crt = false;
                                if(k+1 < n and matAlc[k+1][l] != -1 and matAlc[k+1][l] < matTempo[k+1][l]) crt = true;
                                if(k-1 >= 0 and matAlc[k-1][l] != -1 and matAlc[k-1][l] < matTempo[k-1][l]) crt = true;
                                if(l+1 < n and matAlc[k][l+1] != -1 and matAlc[k][l+1] < matTempo[k][l+1]) crt = true;
                                if(l-1 >= 0 and matAlc[k][l-1] != -1 and matAlc[k][l-1] < matTempo[k][l-1]) crt = true;
                            } 
                            if(crt) {
                                grafo.add(pos[i][j], n2+pos[k][l], lmt);
                            }
                        }
                    }
                }
            }
        }
    }

    loop(i, 0, n) {
        loop(j, 0, n) {
            if(isdigit(caps[i][j])) {
                grafo.add(n2+pos[i][j], nMax+1, caps[i][j] - '0');
            }
        }
    }

    ll ans = grafo.flow();
    cout << ans << '\n';
}
